import "server-only";
import { randomUUID } from "node:crypto";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";

// Works with any S3-compatible service (AWS S3, Cloudflare R2, MinIO, ...).
export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

const EXT_BY_TYPE: Record<string, string> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
  "image/gif": "gif",
};

// Verify the actual bytes, not the client-supplied Content-Type.
function sniffType(b: Uint8Array): string | undefined {
  const ascii = (from: number, to: number) =>
    String.fromCharCode(...b.slice(from, to));
  if (b[0] === 0x89 && ascii(1, 4) === "PNG") return "image/png";
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return "image/jpeg";
  if (ascii(0, 3) === "GIF") return "image/gif";
  if (ascii(0, 4) === "RIFF" && ascii(8, 12) === "WEBP") return "image/webp";
  return undefined;
}

function env(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`Missing env var ${name}`);
  return v;
}

let client: S3Client | undefined;
function getClient() {
  client ??= new S3Client({
    region: env("S3_REGION"),
    endpoint: process.env.S3_ENDPOINT || undefined,
    forcePathStyle: Boolean(process.env.S3_ENDPOINT),
    credentials: {
      accessKeyId: env("S3_ACCESS_KEY_ID"),
      secretAccessKey: env("S3_SECRET_ACCESS_KEY"),
    },
  });
  return client;
}

export class UploadError extends Error {}

/** Validates and stores an image; returns its public URL. */
export async function uploadImage(file: File, ownerId: string): Promise<string> {
  if (file.size === 0) throw new UploadError("Choose an image to upload.");
  if (file.size > MAX_IMAGE_BYTES) throw new UploadError("Image must be 5 MB or smaller.");

  const body = new Uint8Array(await file.arrayBuffer());
  const type = sniffType(body);
  if (!type) throw new UploadError("Only PNG, JPEG, WebP or GIF images are allowed.");

  // Server-generated key: never use the user's filename.
  const key = `notes/${ownerId}/${randomUUID()}.${EXT_BY_TYPE[type]}`;
  await getClient().send(
    new PutObjectCommand({
      Bucket: env("S3_BUCKET"),
      Key: key,
      Body: body,
      ContentType: type,
      CacheControl: "public, max-age=31536000, immutable",
    }),
  );
  return `${env("S3_PUBLIC_BASE_URL").replace(/\/$/, "")}/${key}`;
}
EOF
